// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }

    function testFuzz_property(address caller, uint256 newMin) public {
        vm.assume(caller != address(0));

        bool okBefore;
        vm.prank(caller);
        try c.SetMinSum(newMin) {
            okBefore = true;
        } catch {
            okBefore = false;
        }

        c.Initialized();

        bool okAfter;
        vm.prank(caller);
        try c.SetMinSum(newMin) {
            okAfter = true;
        } catch {
            okAfter = false;
        }

        assertTrue(okBefore && !okAfter);
    }
}
